import java.util.*;

public class Codec {
  // preorder of a BST determines it, so no null markers are needed
  public String serialize(TreeNode root) {
    StringBuilder sb = new StringBuilder();
    preorder(root, sb);
    return sb.toString();
  }

  private void preorder(TreeNode node, StringBuilder sb) {
    if (node == null) return;
    if (sb.length() > 0) sb.append(',');
    sb.append(node.val);
    preorder(node.left, sb);
    preorder(node.right, sb);
  }

  private int pos;

  public TreeNode deserialize(String data) {
    if (data.isEmpty()) return null;
    String[] parts = data.split(",");
    int[] vals = new int[parts.length];
    for (int i = 0; i < parts.length; i++) vals[i] = Integer.parseInt(parts[i]);
    pos = 0;
    return build(vals, Integer.MIN_VALUE, Integer.MAX_VALUE);
  }

  private TreeNode build(int[] vals, int lo, int hi) {
    if (pos == vals.length || vals[pos] < lo || vals[pos] > hi) return null;
    TreeNode node = new TreeNode(vals[pos++]);
    node.left = build(vals, lo, node.val);
    node.right = build(vals, node.val, hi);
    return node;
  }
}
